/* global d3 */
(() => {
  const chartEl = d3.select('#chart');
  const legendEl = d3.select('#legend');
  const tooltip = d3.select('#tooltip');

  const width = chartEl.node().clientWidth || 640;
  const height = 540;

  const svg = chartEl.append('svg')
    .attr('viewBox', `0 0 ${width} ${height}`)
    .attr('width', '100%')
    .attr('height', height)
    .attr('role', 'img')
    .attr('aria-label', 'Bubble chart of stocks grouped by sector');

  const formatMarketCap = (value) => {
    if (!Number.isFinite(value)) return 'N/A';
    return d3.format('.2s')(value).replace('G', 'B');
  };

  const parseRow = (d) => {
    const marketCap = Number(d.marketCap);
    const sector = d.sector && d.sector.trim() ? d.sector.trim() : 'Unknown';
    return {
      ticker: d.ticker,
      fullName: d['full name'] || d['full_name'] || d['fullName'] || 'Unknown',
      sector,
      marketCap: Number.isFinite(marketCap) ? marketCap : NaN,
      isEtf: !Number.isFinite(marketCap)
    };
  };

  const center = { x: width / 2, y: height / 2 };

  d3.csv('data/stock-descriptions.csv', parseRow).then((data) => {
    const filtered = data.filter(d => d.ticker);

    const sectors = Array.from(new Set(filtered.map(d => d.sector))).sort();
    const palette = ([])
      .concat(d3.schemeTableau10 || [])
      .concat(d3.schemeSet3 || [])
      .concat(d3.schemeSet2 || [])
      .concat(d3.schemePaired || []);

    const range = palette.length >= sectors.length
      ? palette.slice(0, sectors.length)
      : d3.quantize(d3.interpolateSpectral, sectors.length).reverse();

    const color = d3.scaleOrdinal().domain(sectors).range(range);

    const capValues = filtered
      .map(d => d.marketCap)
      .filter(v => Number.isFinite(v));

    const capExtent = d3.extent(capValues);
    const rScale = d3.scaleSqrt()
      .domain(capExtent)
      .range([12, 46]);

    const etfRadius = 16;

    filtered.forEach(d => {
      d.r = Number.isFinite(d.marketCap) ? rScale(d.marketCap) : etfRadius;
      d.marketCapFmt = formatMarketCap(d.marketCap);
    });

    const ringRadius = Math.min(width, height) * 0.22;
    const angleStep = (2 * Math.PI) / Math.max(sectors.length, 1);
    const centers = new Map(
      sectors.map((sector, index) => {
        const angle = index * angleStep;
        return [sector, {
          x: center.x + ringRadius * Math.cos(angle),
          y: center.y + ringRadius * Math.sin(angle)
        }];
      })
    );

    const nodeLayer = svg.append('g').attr('class', 'nodes');

    const nodes = nodeLayer.selectAll('g.node')
      .data(filtered, d => d.ticker)
      .enter()
      .append('g')
      .attr('class', 'node');

    nodes.append('circle')
      .attr('r', d => d.r)
      .attr('fill', d => color(d.sector));

    nodes.append('text')
      .text(d => d.ticker)
      .attr('dy', '0.35em');

    const simulation = d3.forceSimulation(filtered)
      .force('x', d3.forceX(d => centers.get(d.sector).x).strength(0.18))
      .force('y', d3.forceY(d => centers.get(d.sector).y).strength(0.18))
      .force('collide', d3.forceCollide(d => d.r + 1))
      .force('charge', d3.forceManyBody().strength(-6))
      .force('center', d3.forceCenter(center.x, center.y))
      .alphaDecay(0.03)
      .on('tick', () => {
        nodes.attr('transform', d => `translate(${d.x},${d.y})`);
      });

    const legendItems = legendEl.selectAll('.legend-item')
      .data(sectors)
      .enter()
      .append('div')
      .attr('class', 'legend-item');

    legendItems.append('span')
      .attr('class', 'legend-swatch')
      .style('background-color', d => color(d));

    legendItems.append('span')
      .attr('class', 'legend-label')
      .text(d => d);

    legendItems.each(function (_, i) {
      this.style.animationDelay = `${0.05 + i * 0.02}s`;
    });

    const tbody = d3.select('#stock-table tbody');
    const rows = tbody.selectAll('tr')
      .data(filtered, d => d.ticker)
      .enter()
      .append('tr')
      .attr('class', 'table-row');

    rows.append('td').text(d => d.ticker);
    rows.append('td').text(d => d.fullName);
    rows.append('td').text(d => d.sector);
    rows.append('td').text(d => d.marketCapFmt);

    let selectedKey = null;

    const setSelected = (ticker) => {
      selectedKey = (selectedKey === ticker || ticker == null) ? null : ticker;
      nodes.classed('selected', d => d.ticker === selectedKey);
      rows.classed('selected', d => d.ticker === selectedKey);

      if (selectedKey) {
        nodes.filter(d => d.ticker === selectedKey).raise();
      }
    };

    nodes.on('click', (event, d) => {
      event.stopPropagation();
      setSelected(d.ticker);
    });

    rows.on('click', (event, d) => {
      event.stopPropagation();
      setSelected(d.ticker);
    });

    svg.on('click', () => setSelected(null));

    const showTooltip = (event, d) => {
      if (d.isEtf) return;
      tooltip
        .style('opacity', 1)
        .html(`<strong>${d.ticker}</strong><br>${d.fullName}<br>${d.sector}`);
      moveTooltip(event);
    };

    const moveTooltip = (event) => {
      tooltip
        .style('left', `${event.pageX + 14}px`)
        .style('top', `${event.pageY + 12}px`);
    };

    const hideTooltip = () => {
      tooltip.style('opacity', 0);
    };

    nodes
      .on('mouseenter', showTooltip)
      .on('mousemove', moveTooltip)
      .on('mouseleave', hideTooltip);

    window.addEventListener('resize', () => {
      simulation.alpha(0.3).restart();
    });
  });
})();
EOF"}

